import pyomo.environ as pyo

DATA = {
    "num_jobs": 6,
    "num_machines": 3,
    "num_positions": 6,
    "jobs": [0, 1, 2, 3, 4, 5],
    "machines": [0, 1, 2],
    "positions": [0, 1, 2, 3, 4, 5],
    # processing time p[job][machine]
    "proc": {
        0: {0: 5, 1: 5, 2: 7},
        1: {0: 5, 1: 9, 2: 10},
        2: {0: 6, 1: 7, 2: 10},
        3: {0: 8, 1: 7, 2: 9},
        4: {0: 9, 1: 5, 2: 9},
        5: {0: 8, 1: 8, 2: 7},
    },
    # objective coefficients on assign[j, last_position] (machine-2 times)
    "obj_coeff_last_pos": {0: 5, 1: 6, 2: 10, 3: 7, 4: 8, 5: 8},
    "last_position": 5,
    "last_machine": 2,
    "big_m": 1000,
}


def build_model(data=None):
    d = data or DATA
    jobs = d["jobs"]
    machines = d["machines"]
    positions = d["positions"]
    proc = d["proc"]
    last_pos = d["last_position"]
    last_mach = d["last_machine"]

    model = pyo.ConcreteModel()

    model.J = pyo.Set(initialize=jobs)
    model.M = pyo.Set(initialize=machines)
    model.K = pyo.Set(initialize=positions)

    # assign[j,k] = 1 if job j occupies position k
    model.assign = pyo.Var(model.J, model.K, within=pyo.Binary)

    # start[k,m] = start time of the job in position k on machine m
    model.start = pyo.Var(model.K, model.M, within=pyo.NonNegativeReals)

    # completion time of the whole schedule
    model.completion = pyo.Var(within=pyo.NonNegativeReals)

    # --- Objective: minimize total completion time ---
    def obj_rule(m):
        return m.start[last_pos, last_mach] + sum(
            d["obj_coeff_last_pos"][j] * m.assign[j, last_pos] for j in m.J
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # --- One job per position ---
    def one_job_per_position_rule(m, k):
        return sum(m.assign[j, k] for j in m.J) == 1

    model.one_job_per_position = pyo.Constraint(model.K, rule=one_job_per_position_rule)

    # --- One position per job ---
    def one_position_per_job_rule(m, j):
        return sum(m.assign[j, k] for k in m.K) == 1

    model.one_position_per_job = pyo.Constraint(model.J, rule=one_position_per_job_rule)

    # --- Machine precedence within a position: machine 1 after machine 0 ---
    def prec_m0_m1_rule(m, k):
        return m.start[k, 1] >= m.start[k, 0] + sum(
            proc[j][0] * m.assign[j, k] for j in m.J
        )

    model.prec_m0_m1 = pyo.Constraint(model.K, rule=prec_m0_m1_rule)

    # --- Machine precedence within a position: machine 2 after machine 1 ---
    def prec_m1_m2_rule(m, k):
        return m.start[k, 2] >= m.start[k, 1] + sum(
            proc[j][1] * m.assign[j, k] for j in m.J
        )

    model.prec_m1_m2 = pyo.Constraint(model.K, rule=prec_m1_m2_rule)

    # --- Job (position) precedence on machine 0 ---
    def job_prec_m0_rule(m, k):
        if k == 0:
            return pyo.Constraint.Skip
        return m.start[k, 0] >= m.start[k - 1, 0] + sum(
            proc[j][0] * m.assign[j, k - 1] for j in m.J
        )

    model.job_prec_m0 = pyo.Constraint(model.K, rule=job_prec_m0_rule)

    # --- Job (position) precedence on machine 1 ---
    def job_prec_m1_rule(m, k):
        if k == 0:
            return pyo.Constraint.Skip
        return m.start[k, 1] >= m.start[k - 1, 1] + sum(
            proc[j][1] * m.assign[j, k - 1] for j in m.J
        )

    model.job_prec_m1 = pyo.Constraint(model.K, rule=job_prec_m1_rule)

    # --- Job (position) precedence on machine 2 ---
    def job_prec_m2_rule(m, k):
        if k == 0:
            return pyo.Constraint.Skip
        return m.start[k, 2] >= m.start[k - 1, 2] + sum(
            proc[j][2] * m.assign[j, k - 1] for j in m.J
        )

    model.job_prec_m2 = pyo.Constraint(model.K, rule=job_prec_m2_rule)

    # --- Completion definition ---
    def completion_rule(m):
        return m.completion >= m.start[last_pos, last_mach] + sum(
            proc[j][last_mach] * m.assign[j, last_pos] for j in m.J
        )

    model.completion_def = pyo.Constraint(rule=completion_rule)

    return model


